import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"探索引用图谱","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/citation-map.md","filePath":"zh/guide/citation-map.md","lastUpdated":1793111003000}'),n={name:"zh/guide/citation-map.md"};function i(p,a,s,d,l,h){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="探索引用图谱" tabindex="-1">探索引用图谱 <a class="header-anchor" href="#探索引用图谱" aria-label="Permalink to &quot;探索引用图谱&quot;">​</a></h1><p>查看检索结果周围的研究联系，而不是逐篇浏览孤立的论文。</p><h2 id="获得图谱" tabindex="-1">获得图谱 <a class="header-anchor" href="#获得图谱" aria-label="Permalink to &quot;获得图谱&quot;">​</a></h2><p>检索前选择 <strong>OpenAlex</strong> 并启用引用扩展，程序会在预算内探索参考文献与施引文献。</p><p>任务结束后从检索结果打开<strong>引用证据</strong>，或进入<strong>文献综述 → 引用证据 → 文献关系</strong>。未收集引用数据时，空图谱是正常状态；切换页面不会自动补做扩展。</p><h2 id="阅读图谱" tabindex="-1">阅读图谱 <a class="header-anchor" href="#阅读图谱" aria-label="Permalink to &quot;阅读图谱&quot;">​</a></h2><p>节点代表论文，箭头从引用他人的论文指向被引用论文。</p><p>图例区分结果、种子、前向和后向扩展角色，表示文献如何进入图谱，不是质量分类。</p><p>点击节点查看论文和原始链接，网络密集时使用图谱控件调整视图。</p><h2 id="理解范围" tabindex="-1">理解范围 <a class="header-anchor" href="#理解范围" aria-label="Permalink to &quot;理解范围&quot;">​</a></h2><p>这是有预算限制的探索，不是整个领域的完整引用网络。数据覆盖、标识符缺失和来源更新会影响连接结果。</p><p>引用数不是相关性评分，近期的相关文献也可能几乎没有引用。</p><p>回到<a href="./results">结果</a>页阅读、选择或导出。</p>',13)])])}const u=t(n,[["render",i]]);export{_ as __pageData,u as default};
